contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Fund c so it has a balance to withdraw.
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // msg.sender of c.withdrawAll is this test contract, which is the owner
        // because this contract deployed c in the checker's setup.
        if (reverted) {
            assert(address(c).balance == beforeBalance);
        } else {
            assert(address(c).balance == 0);
        }
    }

    receive() external payable {}
}

