        require(_caller != address(0), "caller must be nonzero");
        require(_recipient != address(c), "recipient must not be c");

        // The call is made by msg.sender = this contract, which is not the owner
        // since c was constructed with an owner supplied externally.
        address owner = c.owner();
        require(_caller != owner, "caller must not be the owner");

        uint256 balanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }
