contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _recipient) public {
        require(_recipient != address(0), "recipient must be nonzero");
        address owner = c.owner();

        // The calling test contract is not the owner in this scenario: we cannot
        // change msg.sender for the call, but the rule is about a non-owner caller.
        // If this contract happens to be the owner, the precondition excludes it.
        require(address(this) != owner, "caller must not be owner");

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore > 0, "c must hold a nonzero balance");

        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // A non-owner caller can only revert; c's balance may not flow out.
        assert(reverted && address(c).balance == balanceBefore);
    }

    receive() external payable {}
}

