        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _recipient) public payable {
        require(_recipient != address(0), "recipient must be nonzero");
        require(_recipient != address(c), "recipient must not be c");

        uint256 balanceBefore = address(c).balance;
        uint256 recipBalanceBefore = _recipient.balance;

        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            (reverted && address(c).balance == balanceBefore && _recipient.balance == recipBalanceBefore) ||
            (!reverted && address(c).balance == 0 && _recipient.balance >= recipBalanceBefore)
